                $"{points} p.p. a mais de uso",
                $"{points} Pkt. mehr verbraucht",
                $"потрачено на {points} п.п. больше");
        }
        if (points < 0)
        {
            var n = -points;
            return T(
                $"페이스보다 {n}%p 덜 씀",
                $"{n} pts less used",
                $"ペースより{n}pt少なく使用",
                $"{n} pts menos de uso",
