    /// <summary>Name of a newer Claude oauth/usage <c>limits[]</c> entry, from its kind and model scope.</summary>
    public string ClaudeLimitEntry(string? kind, string? model)
    {
        switch (kind)
        {
            case "session": return FiveHourSession;
            case "weekly_all": return Weekly;
            case "weekly_scoped":
                // Without a model name this would read like the legacy "Weekly" row, so mark it as scoped.
                if (model == null) return T("주간 (모델별)", "Weekly (scoped)", "週間（モデル別）", "Semanal (por modelo)", "Hebdo (par modèle)", "Semanal (por modelo)", "Wöchentlich (pro Modell)", "Неделя (по моделям)");
                return T($"주간 {model}", $"Weekly {model}", $"週間 {model}", $"Semanal {model}", $"Hebdo {model}", $"Semanal {model}", $"{model} – wöchentlich", $"{model} — неделя");
            default:
                var name = model == null ? "" : " " + model;
                return (kind ?? "limit").Replace("_", " ") + name;
        }
    }

    /// <summary>Codex limit window name (from windowDurationMins). Shared by notifications and the popover.</summary>
    public string CodexWindow(int? mins)
    {
        switch (mins)
        {
            case 300: return FiveHourSession;
            case 10_080: return Weekly;
            case int m when m >= 60 && m % 60 == 0:
                var h = m / 60;
                return T($"{h}시간", $"{h}h", $"{h}時間", $"{h}h", $"{h} h", $"{h}h", $"{h} Std.", $"{h} ч");
            case int m: return T($"{m}분", $"{m}m", $"{m}分", $"{m}m", $"{m} min", $"{m} min", $"{m} Min.", $"{m} мин");
            default: return T("한도", "Limit", "上限", "Límite", "Limite", "Limite", "Limit", "Лимит");
        }
    }

