    /// <summary>
    /// API <c>displayName</c> ("Gemini Models", "Claude and GPT models", …) → app-language label.
    /// Popover, limit alerts, candy alerts and pet bubbles must share this mapping or one screen shows two languages (#322).
    /// Same axis as <c>AntigravityRateLimitStatus.geminiGroup</c> / <c>thirdPartyGroup</c> (gemini / claude|gpt|3p);
    /// unknown names keep the API string.
    /// </summary>
    public string AntigravityGroupTitle(string displayName)
    {
        bool Has(string s) => displayName.Contains(s, StringComparison.CurrentCultureIgnoreCase);
        if (Has("gemini")) return AntigravityGeminiGroup;
        if (Has("claude") || Has("gpt") || Has("3p")) return AntigravityThirdPartyGroup;
        return displayName;
    }
    public string AntigravityWindow(string? window, string bucketId)
    {
        if (window == "5h" || bucketId.Contains("5h", StringComparison.Ordinal)) return FiveHourSession;
        if (window == "weekly" || bucketId.Contains("weekly", StringComparison.Ordinal)) return Weekly;
        return T("한도", "Limit", "上限", "Límite", "Limite", "Limite", "Limit", "Лимит");
    }

