    /// <summary>Current multiplier next to the slider: 10%–200%, 1.0 = 100%.</summary>
    public string DifficultyValue(double value)
    {
        var percent = value * 100;
        if (percent >= 10) return TokenFormatter.Printf(percent, 0) + "%";
        if (percent >= 1) return TokenFormatter.Printf(percent, 1) + "%";
        return TokenFormatter.Printf(percent, 2) + "%";
    }
