    /// <summary>
    /// Import failure → user message. Kept here, not in the view, so the mapping is testable: when it misses,
    /// the raw "The operation couldn't be completed…" text leaks through.
    /// </summary>
    /// <remarks>
    /// Takes the Swift <c>SaveTransferError</c> case name ("notASaveFile", "newerSchema", "fileTooLarge",
    /// "backupFailed") until that type is ported; any other failure goes through <see cref="UserFacingError"/>.
    /// </remarks>
    public string ImportErrorMessage(string saveTransferErrorCase) => saveTransferErrorCase switch
    {
        "notASaveFile" => ImportErrorNotSaveFile,
        "newerSchema" => ImportErrorNewerSchema,
        "fileTooLarge" => ImportErrorTooLarge,
        "backupFailed" => ImportErrorBackupFailed,
        _ => throw new ArgumentOutOfRangeException(nameof(saveTransferErrorCase), saveTransferErrorCase, null),
    };
