    /// <remarks>Takes the Swift <c>Rarity</c> raw value, or null for the basic egg.</remarks>
    public string EggDescription(string? tier)
    {
        if (tier == null || tier == "common")
        {
            return T(
                "지금 포켓몬을 놓아주고 새 알로 다시 시작해요.",
                "Send off your current Pokémon and start fresh with a new egg.",
